//go:build ignore
package main
import ("fmt"; "go/ast"; "go/types"; "golang.org/x/tools/go/packages")
func count(pkgPath, name string, method bool) int {
	cfg := &packages.Config{Mode: packages.NeedTypes|packages.NeedTypesInfo|packages.NeedSyntax, Dir:"/bench/repo", Tests:true}
	pkgs,_ := packages.Load(cfg, "./...")
	seen := map[string]bool{}; n:=0
	for _, pkg := range pkgs {
		if pkg.TypesInfo==nil { continue }
		for _, f := range pkg.Syntax {
			ast.Inspect(f, func(node ast.Node) bool {
				call, ok := node.(*ast.CallExpr); if !ok { return true }
				switch fun := call.Fun.(type) {
				case *ast.Ident:
					if obj, ok := pkg.TypesInfo.Uses[fun].(*types.Func); ok && obj.Pkg()!=nil && obj.Pkg().Path()==pkgPath && obj.Name()==name {
						pos := pkg.Fset.Position(call.Pos()); key := fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column)
						if !seen[key] { seen[key]=true; n++ }
					}
				case *ast.SelectorExpr:
					if obj, ok := pkg.TypesInfo.Uses[fun.Sel].(*types.Func); ok && obj.Pkg()!=nil && obj.Pkg().Path()==pkgPath && obj.Name()==name {
						pos := pkg.Fset.Position(call.Pos()); key := fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column)
						if !seen[key] { seen[key]=true; n++ }
					}
				}
				return true
			})
		}
	}
	return n
}
func main() {
	targets := [][2]string{{"github.com/usememos/memos/internal/filter","addArg"},{"github.com/usememos/memos/internal/filter","CompileToStatement"},{"github.com/usememos/memos/internal/filter","Field"},{"github.com/usememos/memos/internal/util","GenUUID"}}
	for _, t := range targets { fmt.Printf("%s.%s = %d\n", t[0], t[1], count(t[0], t[1], false)) }
}
EOF
go run verify_top.go 2>&1

