package main
import ("fmt"; "go/ast"; "go/types"; "path/filepath"; "sort"; "strings"; "golang.org/x/tools/go/packages")
const m = "github.com/usememos/memos"
func isDL(p string) bool { return p==m+"/store"||strings.HasPrefix(p,m+"/store/")||p==m+"/store_test" }
func isTF(f string) bool { return strings.HasSuffix(f,"_test.go") }
func base(t types.Type) types.Type { for { switch u:=t.(type){case *types.Pointer,*types.Slice: t=u.Elem(); default: return t} } }
func main() {
 cfg:=&packages.Config{Mode: packages.NeedTypes|packages.NeedTypesInfo|packages.NeedSyntax|packages.NeedDeps, Tests:true, Dir:"/bench/repo"}
 pkgs,_:=packages.Load(cfg,m+"/...")
 var sp *packages.Package
 for _,p:=range pkgs { if p.PkgPath==m+"/store" { sp=p; break } }
 ents:=[]string{"Memo","User","Attachment"}
 objs:=map[string]*types.TypeName{}
 for _,e:=range ents { objs[e]=sp.Types.Scope().Lookup(e).(*types.TypeName) }
 res:=map[string]map[string]map[string]bool{} // entity->pkg->prod/test
 for _,pkg:=range pkgs {
  if isDL(pkg.PkgPath)||pkg.TypesInfo==nil { continue }
  for _,file:=range pkg.Syntax {
   if file==nil { continue }
   fn:=pkg.Fset.Position(file.FileStart).Filename
   kind:="prod"; if isTF(fn) { kind="test" }
   visit:=func(t types.Type){ if t==nil { return }
    for _,e:=range ents { n,ok:=base(t).(*types.Named); if ok&&n.Obj()==objs[e].Obj() {
     if res[e]==nil { res[e]=map[string]map[string]bool{} }
     if res[e][pkg.PkgPath]==nil { res[e][pkg.PkgPath]=map[string]bool{} }
     res[e][pkg.PkgPath][kind]=true
    }}
   }
   for _,tv:=range pkg.TypesInfo.Uses { if pkg.Fset.Position(tv.Pos()).Filename==fn { visit(tv.Type()) } }
   for _,tv:=range pkg.TypesInfo.Defs { if tv!=nil&&tv.Pos().IsValid()&&pkg.Fset.Position(tv.Pos()).Filename==fn { visit(tv.Type()) } }
   ast.Inspect(file,func(n ast.Node)bool{ switch x:=n.(type){case *ast.Ident: if tv,ok:=pkg.TypesInfo.Uses[x];ok{visit(tv.Type())} }; return true })
  }
 }
 for _,e:=range ents {
  fmt.Printf("\n%s:\n",e)
  var prod,test,all []string
  for pkg,m:=range res[e] { short:=strings.TrimPrefix(pkg,m+"/"); all=append(all,short)
   if m["prod"] { prod=append(prod,short) } else if m["test"] { test=append(test,short) }
  }
  sort.Strings(prod); sort.Strings(test); sort.Strings(all)
  fmt.Printf("  prod(%d): %v\n",len(prod),prod)
  fmt.Printf("  test-only(%d): %v\n",len(test),test)
 }
}
EOF
